-- Pre-1e407614 db-bootstrap.psql:23-24 (removed 2026-09-25): ran on every boot.
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO anon, authenticated;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'osionos_account_user') THEN CREATE ROLE osionos_account_user LOGIN BYPASSRLS; CREATE ROLE legacy_grantor CREATEROLE; GRANT service_role TO legacy_grantor WITH ADMIN OPTION; GRANT service_role TO osionos_account_user GRANTED BY legacy_grantor; ALTER ROLE authenticator INHERIT; END IF; END $$; -- a hand-made account role: LOGIN and BYPASSRLS (the account migration must normalize it, check k7), a membership in service_role granted by a CREATEROLE role, not by postgres (the migration must revoke it naming the grantor: a revoke without GRANTED BY only removes what postgres granted, so this membership would survive it and keep the account role inside service_role's privileges), and an authenticator that inherits (the shape db-bootstrap.psql leaves on an existing authenticator: it alters it without NOINHERIT — so the migration must put INHERIT FALSE on the MEMBERSHIP, not rely on the role). The guard keeps this file replayable.